# Deeper investigation of Wilson CI discrepancies
# The paper might be using floor/ceil or a slightly different rounding convention
import math

def wilson_ci(k, n, z=1.96):
    p = k / n
    denom = 1 + z**2 / n
    center = (p + z**2 / (2*n)) / denom
    margin = z * math.sqrt(p*(1-p)/n + z**2/(4*n**2)) / denom
    return (center - margin, center + margin)

# Check if truncation (floor for lower, ceil for upper) matches
discrepant = [
    ("seed1",   32, 134, (17.4, 31.8)),
    ("seed6",   39, 134, (22.2, 37.1)),
    ("seed2048",11, 134, ( 4.6, 14.2)),
