    ("seed8",   18, 134, ( 8.6, 20.3)),
    ("seed5",   34, 134, (18.8, 33.3)),
    ("seed4",   41, 134, (23.5, 38.7)),
]

print("Detailed analysis of discrepant Wilson CIs:")
print("-" * 70)
for name, k, n, (rep_lo, rep_hi) in discrepant:
    lo, hi = wilson_ci(k, n)
    lo_pct = lo * 100
    hi_pct = hi * 100

    # Various rounding strategies
    lo_round = round(lo_pct, 1)
    hi_round = round(hi_pct, 1)
    lo_floor = math.floor(lo_pct * 10) / 10
    hi_ceil = math.ceil(hi_pct * 10) / 10
    lo_trunc = int(lo_pct * 10) / 10
    hi_trunc = int(hi_pct * 10) / 10

    print(f"{name} (k={k}):")
    print(f"  Exact:     [{lo_pct:.4f}, {hi_pct:.4f}]")
    print(f"  round():   [{lo_round}, {hi_round}]")
    print(f"  floor/ceil:[{lo_floor}, {hi_ceil}]")
    print(f"  Reported:  [{rep_lo}, {rep_hi}]")

    # Check difference magnitude
    lo_diff = abs(lo_pct - rep_lo * 1)  # compare to reported * 1 (already in %)
    hi_diff = abs(hi_pct - rep_hi * 1)
    print(f"  Diff:      lo={lo_diff:.2f}pp, hi={hi_diff:.2f}pp")
    print()

# Check Fisher p=0.02 more carefully
from scipy.stats import fisher_exact, chi2_contingency

print("=" * 70)
print("FISHER EXACT TEST: seed2 detailed")
print("=" * 70)
table = [[21, 134-21], [9, 134-9]]
